CG3_INLINE bool checkSegmentIntersection2D(
        const Segment2d& seg1, const Segment2d& seg2,
        const bool& ignoreEndPoints)
{
    Point2d p1From = seg1.p1();
    Point2d p1To = seg1.p2();
    Point2d p2From = seg2.p1();
    Point2d p2To = seg2.p2();
    double eps = 0.001;

