{
public:
    /* Constructors/destructor */
    Segment();
    Segment(const T& p1, const T& p2);

    /* Getters */
    inline const T& p1() const;
    inline const T& p2() const;

    /* Setters */
    inline void setP1(const T& p1);
    inline void setP2(const T& p2);
