    /* Operator overrides */
    inline bool operator == (const Segment& otherSegment) const;
    inline bool operator != (const Segment& otherSegment) const;
    inline bool operator < (const Segment& otherSegment) const;
    inline bool operator > (const Segment& otherSegment) const;
    inline bool operator <= (const Segment& otherSegment) const;
    inline bool operator >= (const Segment& otherSegment) const;

    /* Serialization */
    void serialize(std::ofstream& binaryFile) const;
    void deserialize(std::ifstream& binaryFile);

    /* Utilities */
    std::string toString() const;

protected:
    /* Fields */
    T _p1;
    T _p2;
};

template<class T>
